Add a 'corporate' customer type to this existing discount service:

```typescript
class DiscountService {
  calculate(order: Order): number {
    if (order.customerType === 'guest') return 0;
    else if (order.customerType === 'member') return order.subtotal * 0.05;
    else if (order.customerType === 'premium') return order.subtotal * 0.15;
    else return 0;
  }
}
